function s(v){return String(v==null?'':v).trim();}
function norm(x){return s(x).toLowerCase().replace(/[^a-z0-9]/g,'');}
const TARGETS=['Riceberg Ventures','Siana Capital','Elevation Capital'];
const trk=$('Read Deal Tracker').all().map(i=>i.json);
const st=$('Read STARTUPS').all().map(i=>i.json);
const pipe=$input.all().map(i=>i.json);
if(pipe.length<500){throw new Error('ABORT: PIPELINE only '+pipe.length+' rows');}
if(trk.length<200){throw new Error('ABORT: tracker only '+trk.length+' rows - truncated');}

const tcols=Object.keys(trk[0]||{});
let cInv=null;const cDeals=[];
for(const c of tcols){const l=c.toLowerCase();if(!cInv&&(l.indexOf('investor')>=0||l.indexOf('vc name')>=0)){cInv=c;}if(l.indexOf('deals shared')>=0||l.indexOf('latest deal')>=0||l.indexOf('picked')>=0){cDeals.push(c);}}
const distinctInv={};for(const r of trk){const k=norm(r[cInv]);if(k)distinctInv[k]=1;}

const trkShared={};
for(const name of TARGETS){const k=norm(name);const list=[];for(const r of trk){if(norm(r[cInv])!==k)continue;for(const c of cDeals){for(const d of s(r[c]).split(/[,;\n]/)){if(s(d).length>2)list.push(s(d));}}}trkShared[name]=list;}

// every startup name mentioned anywhere in the tracker deal columns, for a global sanity view
const pcols=Object.keys(pipe[0]||{});
let maxId=0;
for(const r of pipe){const m=s(r.deal_id).match(/(\d+)/);if(m){const n=parseInt(m[1],10);if(n>maxId)maxId=n;}}

const byInv={};
for(const name of TARGETS){const rows=pipe.filter(r=>s(r.investor)===name);byInv[name]=rows.map(r=>({row_number:r.row_number,deal_id:s(r.deal_id),startup:s(r.startup),deal_shared:s(r.deal_shared),investor_response:s(r.investor_response).slice(0,60),pause:s(r.pause),next_due:s(r.next_due),next_action:s(r.next_action),priority:s(r.priority),owner:s(r.owner),notes:s(r.notes).slice(0,80)}));}

const scols=Object.keys(st[0]||{});
const startups=st.map(r=>{const o={};for(const k of scols){o[k]=s(r[k]).slice(0,400);}return o;});

const dueCount={};
for(const r of pipe){const d=s(r.next_due);if(d&&s(r.deal_shared).toLowerCase()!=='yes')dueCount[d]=(dueCount[d]||0)+1;}

return [{json:{tracker_rows:trk.length,tracker_distinct_investors:Object.keys(distinctInv).length,tracker_columns:tcols,tracker_investor_col:cInv,tracker_deal_cols:cDeals,tracker_shared_for_targets:trkShared,pipeline_rows:pipe.length,pipeline_columns:pcols,max_deal_id_num:maxId,pipeline_for_targets:byInv,startups_count:st.length,startups:startups,pending_next_due_counts:dueCount}}];
